{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Verapamil, the closest structural analogue, has an absolute oral bioavailability of 34% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "In normal subjects, verapamil absolute bioavailability was 22.0%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "One verapamil study in normal young men reported mean bioavailability of 19.4%, slightly below the 20% threshold, indicating borderline variability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Noscapine, a transferable analogue, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Praziquantel, another transferable analogue, showed 27.2% bioavailability in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a verapamil-like lipophilic basic molecule. The closest analogue verapamil has absolute oral bioavailability mostly in the 20–38% range, and other transferable analogues (noscapine, praziquantel) show 27–30%, collectively supporting F ≥ 20%. One verapamil study reports 19.4%, but the weight of evidence favors high.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the exact query molecule; prediction relies on close analogues.",
    "Verapamil bioavailability is variable and near the 20% threshold, with some studies reporting <20%.",
    "The query's lactam and indane modifications may alter first-pass metabolism relative to verapamil, but the direction of any effect is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

